import React, { useState } from 'react';
import './RegexSearch.css';

const API_URL = "http://localhost:5000/api";

function RegexSearch() {
  const [pattern, setPattern] = useState('');
  const [searchIn, setSearchIn] = useState('title');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [searchPerformed, setSearchPerformed] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!pattern.trim()) return;

    setLoading(true);
    setError(null);
    setSearchPerformed(true);

    try {
      const response = await fetch(
        `${API_URL}/search/regex?pattern=${encodeURIComponent(pattern)}&in=${searchIn}`
      );
      const data = await response.json();
      
      if (data.error) {
        setError(data.error);
        setResults([]);
      } else {
        setResults(data);
      }
    } catch (err) {
      setError('Erreur de connexion au serveur');
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  const examplePatterns = [
    { pattern: '^The', desc: 'Titres commençant par "The"' },
    { pattern: 'love$', desc: 'Titres finissant par "love"' },
    { pattern: '[0-9]+', desc: 'Contenant des chiffres' },
    { pattern: 'war|peace', desc: 'Contenant "war" ou "peace"' },
    { pattern: '^[A-Z]{3,}', desc: 'Commençant par 3+ majuscules' },
  ];

  return (
    <div className="regex-search">
      <div className="regex-header">
        <h2>🔤 Recherche par Expression Régulière</h2>
        <p className="regex-subtitle">Utilisez des patterns RegEx pour des recherches avancées</p>
      </div>

      <form onSubmit={handleSearch} className="regex-form">
        <div className="input-group">
          <label htmlFor="pattern">Pattern RegEx</label>
          <input
            type="text"
            id="pattern"
            value={pattern}
            onChange={(e) => setPattern(e.target.value)}
            placeholder="Ex: ^The.*love$"
            className="regex-input"
          />
        </div>

        <div className="search-options">
          <label className="radio-label">
            <input
              type="radio"
              value="title"
              checked={searchIn === 'title'}
              onChange={(e) => setSearchIn(e.target.value)}
            />
            <span className="radio-custom"></span>
            Rechercher dans les titres
          </label>
          <label className="radio-label">
            <input
              type="radio"
              value="content"
              checked={searchIn === 'content'}
              onChange={(e) => setSearchIn(e.target.value)}
            />
            <span className="radio-custom"></span>
            Rechercher dans le contenu
          </label>
        </div>

        <button type="submit" className="search-btn" disabled={loading}>
          {loading ? '⏳ Recherche...' : '🔍 Rechercher'}
        </button>
      </form>

      <div className="examples-section">
        <h3>💡 Exemples de patterns</h3>
        <div className="examples-grid">
          {examplePatterns.map((ex, i) => (
            <button
              key={i}
              className="example-btn"
              onClick={() => setPattern(ex.pattern)}
            >
              <code>{ex.pattern}</code>
              <span>{ex.desc}</span>
            </button>
          ))}
        </div>
      </div>

      {error && (
        <div className="regex-error">
          <span>⚠️</span> {error}
        </div>
      )}

      {loading && (
        <div className="regex-loading">
          <div className="spinner"></div>
          <p>Analyse du pattern en cours...</p>
        </div>
      )}

      {!loading && searchPerformed && (
        <div className="regex-results">
          <h3>📚 Résultats ({results.length} livres trouvés)</h3>
          {results.length === 0 ? (
            <p className="no-results">Aucun livre ne correspond à ce pattern.</p>
          ) : (
            <div className="results-list">
              {results.map((book) => (
                <div key={book.id} className="regex-result-card">
                  <h4>{book.titre}</h4>
                  <div className="book-meta">
                    <span>📖 {book.nb_mots?.toLocaleString()} mots</span>
                    <span>🆔 ID: {book.id}</span>
                  </div>
                  {book.extrait && (
                    <p className="book-extract">
                      {book.extrait.substring(0, 200)}...
                    </p>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      <div className="regex-help">
        <h3>📖 Guide RegEx</h3>
        <table className="help-table">
          <tbody>
            <tr><td><code>.</code></td><td>N'importe quel caractère</td></tr>
            <tr><td><code>*</code></td><td>0 ou plusieurs occurrences</td></tr>
            <tr><td><code>+</code></td><td>1 ou plusieurs occurrences</td></tr>
            <tr><td><code>?</code></td><td>0 ou 1 occurrence</td></tr>
            <tr><td><code>^</code></td><td>Début de chaîne</td></tr>
            <tr><td><code>$</code></td><td>Fin de chaîne</td></tr>
            <tr><td><code>[abc]</code></td><td>Un caractère parmi a, b, c</td></tr>
            <tr><td><code>[0-9]</code></td><td>Un chiffre</td></tr>
            <tr><td><code>a|b</code></td><td>a ou b</td></tr>
            <tr><td><code>(groupe)</code></td><td>Groupement</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default RegexSearch;
